                try {
                    _outputStream.write(raw, 0, len);
                } catch (IOException e) {
                    throw _wrapIOFailure(e);
                }
                return outputPtr;
            }
        }
        System.arraycopy(raw, 0, outputBuffer, outputPtr, len);
        outputPtr += len;
